// Normaliza o que chega de /api/gerar-questoes e monta o prompt.
// O prompt vive aqui, e não no código do site, justamente para a coordenação
// pedagógica poder ajustar sem depender de deploy.

const e = $input.first().json.body || $input.first().json;

const titulo     = (e.titulo     || '').toString().trim();
const descricao  = (e.descricao  || '').toString().trim();
const nivel      = (e.nivel      || 'Iniciante').toString().trim();
const curso      = (e.curso      || '').toString().trim();
const modulo     = (e.modulo     || '').toString().trim();
const categoria  = (e.categoria  || 'Contabilidade').toString().trim();
const quantidade = Math.min(Math.max(parseInt(e.quantidade || 5, 10) || 5, 1), 10);

if (!titulo) {
  throw new Error('O título da aula é obrigatório.');
}

const calibragem = {
  'Iniciante':     'Cobre definição, finalidade e o passo básico da rotina. O distrator deve ser um engano comum de quem está começando, nunca uma pegadinha de redação.',
  'Intermediário': 'Cobre aplicação em situação concreta do escritório. Peça o porquê da decisão, não só o nome do conceito. O distrator deve ser plausível para quem sabe a teoria mas nunca executou.',
  'Avançado':      'Cobre exceção, conflito de regra e consequência de escolher errado. O distrator deve ser a resposta certa em outro contexto — o que separa quem domina de quem decorou.'
};

const system = `Você monta avaliações para a Castelo Branco Academy, escola de contabilidade da Castelo Branco Contabilidade Avançada — mais de 20 anos em Feira de Santana/BA, contabilidade consultiva com foco em transporte, logística, armazenagem e comércio exterior.

COMO A ESCOLA PENSA
A Castelo Branco trabalha por camadas de segurança: da C1 (o que é pacífico e documentado) até a C4 (crédito inexistente, passivo oculto, decisão sem sustentação legal). Nada da C4 entra em material de ensino. Se um tema tem controvérsia real, a questão trata a controvérsia como controvérsia — não escolhe lado como se fosse consenso.

O QUE FAZ UMA BOA QUESTÃO AQUI
O aluno é profissional de escritório contábil, não candidato a concurso. A questão vale quando ele erra por não saber executar, e não por não ter lido com atenção. Prefira sempre a decisão prática à definição decorada.

REGRAS DE FORMATO
1. Quatro alternativas, ids "a", "b", "c" e "d".
2. Uma única correta. Varie a letra certa entre as questões.
3. Alternativas de comprimento parecido. A mais longa não pode ser sempre a correta.
4. Nada de "todas as anteriores", "nenhuma das anteriores" ou negativa dupla.
5. Enunciado direto, no máximo três linhas, em português brasileiro.
6. A explicação diz por que a correta está certa E por que o erro mais provável está errado. Duas a quatro linhas.
7. Não invente número, prazo, alíquota ou artigo de lei do qual você não tenha certeza. Na dúvida, faça a questão sobre o raciocínio, não sobre o número.
8. Nada de pergunta sobre a plataforma, o instrutor ou a duração da aula.

Responda APENAS com JSON válido, sem cerca de código e sem comentário.`;

const user = `Gere exatamente ${quantidade} questões de múltipla escolha sobre esta aula.

AULA
Curso: ${curso || 'não informado'}
Módulo: ${modulo || 'não informado'}
Título: ${titulo}
Descrição: ${descricao || 'não informada'}
Área: ${categoria}
Nível: ${nivel}

CALIBRAGEM PARA O NÍVEL ${nivel.toUpperCase()}
${calibragem[nivel] || calibragem['Iniciante']}

Formato exato da resposta:
{"questoes":[{"enunciado":"...","alternativas":[{"id":"a","texto":"..."},{"id":"b","texto":"..."},{"id":"c","texto":"..."},{"id":"d","texto":"..."}],"correta":"b","explicacao":"..."}]}`;

return [{ json: { system, user, quantidade, titulo, nivel } }];

// Valida antes de devolver. Questão sem gabarito válido é pior que questão
// nenhuma: o admin aprovaria sem perceber e o aluno erraria a certa.

const LETRAS = ['a', 'b', 'c', 'd'];
const bruto = $input.first().json;
const texto = bruto?.content?.[0]?.text ?? '';

function extrair(t) {
  const limpo = String(t).replace(/```(?:json)?/gi, '').trim();
  try { return JSON.parse(limpo); } catch (_) {}
  const i = limpo.indexOf('{');
  const f = limpo.lastIndexOf('}');
  if (i === -1 || f <= i) return null;
  try { return JSON.parse(limpo.slice(i, f + 1)); } catch (_) { return null; }
}

const dados = extrair(texto);
const lista = Array.isArray(dados) ? dados : (dados?.questoes ?? []);

const questoes = [];
for (const item of (Array.isArray(lista) ? lista : [])) {
  const enunciado = typeof item?.enunciado === 'string' ? item.enunciado.trim() : '';
  if (!enunciado) continue;

  const alternativas = (Array.isArray(item?.alternativas) ? item.alternativas : [])
    .map((a, i) => {
      const txt = typeof a?.texto === 'string' ? a.texto.trim() : (typeof a === 'string' ? a : '');
      const id  = typeof a?.id === 'string' && LETRAS.includes(a.id.toLowerCase())
        ? a.id.toLowerCase() : LETRAS[i];
      return txt && id ? { id, texto: txt } : null;
    })
    .filter(Boolean)
    .slice(0, 4);

  if (alternativas.length < 2) continue;

  const correta = typeof item?.correta === 'string' ? item.correta.trim().toLowerCase() : '';
  if (!alternativas.some((a) => a.id === correta)) continue;

  questoes.push({
    enunciado,
    alternativas,
    correta,
    explicacao: typeof item?.explicacao === 'string' ? item.explicacao.trim() : ''
  });
}

if (questoes.length === 0) {
  // Devolver vazio faz a rota /api/gerar-questoes cair no caminho seguinte
  // em vez de entregar lixo ao admin.
  return [{ json: { questoes: [], erro: 'O modelo não devolveu questões utilizáveis.' } }];
}

return [{ json: { questoes } }];
